/* Natural proportions and identical theme rules for HTML and React surfaces. */
.qva-brand{display:inline-block;vertical-align:middle;width:var(--brand-width,200px);max-width:100%;line-height:0;flex-shrink:0}
.qva-brand>img{display:block;width:100%;height:auto;max-width:100%;border-radius:0;filter:none}
.qva-brand>.qva-brand-inverse{display:none}
.qva-brand-symbol{--brand-width:56px}
[data-theme="dark"] .qva-brand>.qva-brand-light{display:none}
[data-theme="dark"] .qva-brand>.qva-brand-inverse{display:block}
@media(prefers-color-scheme:dark){:root:not([data-theme]) .qva-brand>.qva-brand-light{display:none}:root:not([data-theme]) .qva-brand>.qva-brand-inverse{display:block}}
[data-theme="light"]{color-scheme:light}
[data-theme="dark"]{color-scheme:dark}
.boot-first-paint{min-height:100dvh}
@media(prefers-color-scheme:dark){:root:not([data-theme]) .boot-first-paint{background:#191714}}

const form = document.querySelector("#login-form");
const status = document.querySelector("#login-status");
const button = form.querySelector("button");

form.addEventListener("submit", async (event) => {
  event.preventDefault();
  button.disabled = true;
  button.textContent = "Verificando…";
  status.textContent = "";
  try {
    const response = await fetch("/api/session", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ password: form.elements.password.value }),
    });
    const payload = await response.json();
    if (!response.ok) throw new Error(payload.error || "No se pudo iniciar sesión.");
    form.reset();
    window.location.reload();
  } catch (error) {
    status.textContent = error instanceof Error ? error.message : "No se pudo conectar.";
    button.disabled = false;
    button.textContent = "Entrar de forma segura";
  }
});

self.addEventListener("push", (event) => {
    let payload = {};
    try { payload = event.data ? event.data.json() : {}; } catch {}
    const alert = payload.alert || {};
    const title = payload.type === "chat-message" || payload.type === "system-health" || payload.type === "informational-summary" ? payload.title || "Actividad de QvaApply" : payload.type === "blocked-offer"
      ? "Oferta requiere revisión"
      : payload.type === "operation-applied"
        ? "Aplicación confirmada"
        : payload.type === "rebalance-completed"
          ? "Reajuste completado"
          : payload.type === "rebalance-attention"
            ? "Reajuste requiere atención"
        : "Actividad de QvaApply";
    const body = payload.type === "chat-message" || payload.type === "system-health" || payload.type === "informational-summary" ? payload.body || "Consulta el estado del bot." : [alert.coin, alert.amount ? alert.amount + " QUSD" : "", alert.reason || ""].filter(Boolean).join(" · ");
    const url = payload.url || "/?view=auditoria";
    event.waitUntil(self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      const visible = clients.find((client) => client.visibilityState === "visible");
      if (visible) { visible.postMessage({ type: "qvaapply-notification", payload }); return; }
      return self.registration.showNotification(title, {
        body,
        tag: payload.version || payload.type,
        data: { url },
        icon: "/logo/encuentro-preciso-icon-192.png",
        badge: "/logo/encuentro-preciso-badge.png",
        requireInteraction: payload.type === "operation-applied" || payload.type === "rebalance-attention"
      });
    }));
  });
  self.addEventListener("notificationclick", (event) => {
    event.notification.close();
    const target = new URL(event.notification.data?.url || "/", self.location.origin).href;
    event.waitUntil(self.clients.matchAll({ type: "window", includeUncontrolled: true }).then(async (clients) => {
      const existing = clients[0];
      if (existing) { await existing.navigate(target); return existing.focus(); }
      return self.clients.openWindow(target);
    }));
  });
